CREATE TABLE IF NOT EXISTS slt_access_grants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE, scope_type slt_scope_type NOT NULL, scope_id UUID, granted_by UUID REFERENCES user_profiles(id), granted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), expires_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ);
